local IS_SERVER = game["Run Service"]:IsServer()
local _func = script._func

local module = {}

function module.GetRemoteEvent(name)
    local instance = script:FindFirstChild(name .. "_RemoteEvent")
    if not instance then
        if IS_SERVER then
            local remoteEvent = Instance.new("RemoteEvent")
            remoteEvent.Name = name .. "_RemoteEvent"
            remoteEvent.Parent = script
            instance = remoteEvent
        else
            local res = _func:InvokeServer("GetRemoteEvent", name)
            instance = res
        end
    end
    return instance
end

function module.GetRemoteFunction(name)
    local instance = script:FindFirstChild(name .. "_RemoteFunction")
    if IS_SERVER then
        if not instance then
            local remoteFunction = Instance.new("RemoteFunction")
            remoteFunction.Name = name .. "_RemoteFunction"
            remoteFunction.Parent = script
            instance = remoteFunction
        end
    else
        local res = _func:InvokeServer("GetRemoteFunction", name)
        instance = res
    end
    return instance
end

function module.GetBindableEvent(name)
    local instance = script:FindFirstChild(name .. "_BindableEvent")
    if not instance then
        local bindableEvent = Instance.new("BindableEvent")
        bindableEvent.Name = name .. "_BindableEvent"
        bindableEvent.Parent = script
        instance = bindableEvent
    end
    return instance
end

function module.GetBindableFunction(name)
    local instance = script:FindFirstChild(name .. "_BindableFunction")
    if not instance then
        local bindableFunction = Instance.new("BindableFunction")
        bindableFunction.Name = name .. "_BindableFunction"
        bindableFunction.Parent = script
        instance = bindableFunction
    end
    return instance
end

if IS_SERVER then
    _func.OnServerInvoke = function(player, cmd, name)
        if cmd == "GetRemoteEvent" then
            return module.GetRemoteEvent(name)
        elseif cmd == "GetRemoteFunction" then
            return module.GetRemoteFunction(name)
        end
    end
end

return module